#!/bin/sh
# Generates Formula/noah.rb (Homebrew) and bucket/noah.json (Scoop) for a release.
# Usage: scripts/packaging.sh vX.Y.Z path/to/SHA256SUMS
# Called by the release workflow; the two files are generated, do not edit them.
set -eu
tag="$1"; sums="$2"
ver="${tag#v}"
repo="dicapower/noah"
base="https://github.com/$repo/releases/download/$tag"

sum() { # sum <os-arch> <ext>
  f="noah-$tag-$1.$2"
  h=$(grep "  $f\$" "$sums" | cut -d' ' -f1)
  [ -n "$h" ] || { echo "packaging: $f missing from $sums" >&2; exit 1; }
  printf '%s' "$h"
}

mkdir -p Formula bucket
cat > Formula/noah.rb <<RB
# Generated by scripts/packaging.sh from the release checksums. Do not edit.
class Noah < Formula
  desc "Persistent memory for AI coding agents (MCP over stdio, SQLite)"
  homepage "https://github.com/$repo"
  version "$ver"
  license "Apache-2.0"

  on_macos do
    on_arm do
      url "$base/noah-$tag-darwin-arm64.tar.gz"
      sha256 "$(sum darwin-arm64 tar.gz)"
    end
    on_intel do
      url "$base/noah-$tag-darwin-amd64.tar.gz"
      sha256 "$(sum darwin-amd64 tar.gz)"
    end
  end

  on_linux do
    on_arm do
      url "$base/noah-$tag-linux-arm64.tar.gz"
      sha256 "$(sum linux-arm64 tar.gz)"
    end
    on_intel do
      url "$base/noah-$tag-linux-amd64.tar.gz"
      sha256 "$(sum linux-amd64 tar.gz)"
    end
  end

  def install
    bin.install "noah"
  end

  def caveats
    <<~EOS
      Restart your agent so it launches the new version, then run: noah doctor
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/noah version")
  end
end
RB

cat > bucket/noah.json <<JSON
{
    "version": "$ver",
    "description": "Persistent memory for AI coding agents (MCP over stdio, SQLite)",
    "homepage": "https://github.com/$repo",
    "license": "Apache-2.0",
    "architecture": {
        "64bit": {
            "url": "$base/noah-$tag-windows-amd64.zip",
            "hash": "$(sum windows-amd64 zip)",
            "extract_dir": "noah-$tag-windows-amd64"
        }
    },
    "bin": "noah.exe",
    "checkver": "github",
    "autoupdate": {
        "architecture": {
            "64bit": {
                "url": "https://github.com/$repo/releases/download/v\$version/noah-v\$version-windows-amd64.zip",
                "extract_dir": "noah-v\$version-windows-amd64"
            }
        }
    }
}
JSON
echo "packaging: wrote Formula/noah.rb and bucket/noah.json for $tag"
